'use client'

import type { ComponentProps } from 'react'
import {
  Slider as UiSlider,
  SliderControl as UiSliderControl,
  SliderIndicator as UiSliderIndicator,
  SliderThumb as UiSliderThumb,
  SliderTrack as UiSliderTrack,
  SliderValue as UiSliderValue,
} from '@ui-sdk/react/slider'

import './slider.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

export { createSliderController } from '@ui-sdk/react/slider'
export type {
  NumberFormat,
  SliderApi,
  SliderChangeOptions,
  SliderController,
  SliderOptions,
  SliderPrimitive,
  SliderState,
  SliderThumbProps as UiSliderThumbProps,
  SliderThumbState,
  SliderValueChangeDetails,
  SliderValueChangeReason,
  SliderValueCommitDetails,
  SliderValueState,
} from '@ui-sdk/react/slider'

export type SliderProps<
  Value extends number | number[] = number | number[],
> = ComponentProps<typeof UiSlider<Value>>

export function Slider<Value extends number | number[] = number | number[]>(
  props: SliderProps<Value>,
) {
  return <UiSlider<Value> {...props} />
}

type UiSliderControlProps = ComponentProps<typeof UiSliderControl>

export type SliderControlProps = Omit<
  UiSliderControlProps,
  'className' | 'render'
> & {
  className?: UiSliderControlProps['className']
  render?: UiSliderControlProps['render']
}

export function SliderControl(props: SliderControlProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSliderControl {...rest} className={props.className} render={props.render} />
}

type UiSliderTrackProps = ComponentProps<typeof UiSliderTrack>

export type SliderTrackProps = Omit<UiSliderTrackProps, 'className' | 'render'> & {
  className?: UiSliderTrackProps['className']
  render?: UiSliderTrackProps['render']
}

export function SliderTrack(props: SliderTrackProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSliderTrack {...rest} className={props.className} render={props.render} />
}

type UiSliderIndicatorProps = ComponentProps<typeof UiSliderIndicator>

export type SliderIndicatorProps = Omit<
  UiSliderIndicatorProps,
  'className' | 'render'
> & {
  className?: UiSliderIndicatorProps['className']
  render?: UiSliderIndicatorProps['render']
}

export function SliderIndicator(props: SliderIndicatorProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiSliderIndicator {...rest} className={props.className} render={props.render} />
  )
}

type UiSliderThumbPartProps = ComponentProps<typeof UiSliderThumb>

export type SliderThumbPartProps = Omit<
  UiSliderThumbPartProps,
  'className' | 'render'
> & {
  className?: UiSliderThumbPartProps['className']
  render?: UiSliderThumbPartProps['render']
}

export function SliderThumb(props: SliderThumbPartProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSliderThumb {...rest} className={props.className} render={props.render} />
}

type UiSliderValueProps = ComponentProps<typeof UiSliderValue>

export type SliderValueProps = Omit<UiSliderValueProps, 'className' | 'render'> & {
  className?: UiSliderValueProps['className']
  render?: UiSliderValueProps['render']
}

export function SliderValue(props: SliderValueProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSliderValue {...rest} className={props.className} render={props.render} />
}

@layer components {
  [data-slot="slider"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
    min-width: 180px;
  }

  [data-slot="slider"][data-orientation="vertical"] {
    width: auto;
    min-width: 0;
    align-items: center;
  }

  [data-slot="slider-header"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
  }

  [data-slot="slider-value"] {
    font-size: 12px;
    font-weight: 440;
    line-height: var(--line-height-compact);
    letter-spacing: -0.02px;
    color: var(--v2-text-text-muted);
    font-variant-numeric: tabular-nums;
    user-select: none;
  }

  [data-slot="slider-value"][data-disabled] {
    opacity: 0.5;
  }

  /* ---------------------------------------------------------------- */
  /* Control hit target                                               */
  /* ---------------------------------------------------------------- */

  [data-slot="slider-control"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    width: 100%;
    height: 20px;
    padding-inline: 7px;
    touch-action: none;
    cursor: pointer;
    user-select: none;
  }

  [data-slot="slider-control"][data-orientation="vertical"] {
    justify-content: center;
    width: 20px;
    height: 144px;
    padding-inline: 0;
    padding-block: 7px;
  }

  [data-slot="slider-control"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ---------------------------------------------------------------- */
  /* 4px rail track                                                   */
  /* ---------------------------------------------------------------- */

  [data-slot="slider-track"] {
    position: relative;
    width: 100%;
    height: 4px;
    border-radius: 999px;
    background: var(--v2-background-bg-layer-02);
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-base);
  }

  [data-slot="slider-track"][data-orientation="vertical"] {
    width: 4px;
    height: 100%;
  }

  /* ---------------------------------------------------------------- */
  /* Filled range indicator                                           */
  /* ---------------------------------------------------------------- */

  [data-slot="slider-indicator"] {
    border-radius: inherit;
    background: var(--v2-background-bg-inverse);
  }

  /* ---------------------------------------------------------------- */
  /* 14px circular thumb                                              */
  /* ---------------------------------------------------------------- */

  [data-slot="slider-thumb"] {
    box-sizing: border-box;
    width: 14px;
    height: 14px;
    border: 0;
    border-radius: 999px;
    background: var(--v2-background-bg-base);
    box-shadow:
      var(--v2-elevation-button-neutral),
      0 0 0 1px var(--v2-border-border-strong);
    cursor: grab;
    transition:
      scale 100ms ease-out,
      box-shadow 100ms ease-out;
  }

  @media (hover: hover) {
    [data-slot="slider-thumb"]:hover:not([data-disabled]) {
      scale: 1.08;
      box-shadow:
        var(--v2-elevation-raised),
        0 0 0 1px var(--v2-icon-icon-muted);
    }
  }

  [data-slot="slider-thumb"][data-dragging]:not([data-disabled]) {
    cursor: grabbing;
    scale: 1.12;
    box-shadow:
      var(--v2-elevation-raised),
      0 0 0 1px var(--v2-background-bg-inverse);
  }

  [data-slot="slider-thumb"]:has(:focus-visible) {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2px;
  }

  [data-slot="slider-thumb"][data-disabled] {
    cursor: not-allowed;
  }

  /* Optional tick marks row */
  [data-slot="slider-marks"] {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding-inline: 7px;
    font-size: 11px;
    font-weight: 440;
    color: var(--v2-text-text-faint);
    font-variant-numeric: tabular-nums;
    user-select: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="slider-thumb"] {
      transition: none;
    }
  }
}
